/* =========================================================
   DO CAMPO AO PORTO – PARANAGUÁ SUSTENTÁVEL
      Agrinho 2026 | style.css
         ========================================================= */

         /* ── 1. CUSTOM PROPERTIES ─────────────────────────────── */
         :root {
           /* Palette — inspired by the bay, soil, and soy fields */
             --c-soil:      #2B1D0E;   /* dark espresso – earth */
               --c-field:     #3A5A2A;   /* deep forest green */
                 --c-soy:       #7BAF3F;   /* vibrant soy green */
                   --c-straw:     #E8C96B;   /* golden straw accent */
                     --c-ocean:     #1B4F72;   /* deep Paranaguá bay */
                       --c-mist:      #D6EAF8;   /* soft mist/sea foam */
                         --c-cream:     #FAF7F2;   /* warm page background */
                           --c-ink:       #1A1A1A;   /* body text */
                             --c-mid:       #555555;
                               --c-light:     #888888;
                                 --c-white:     #FFFFFF;
                                   --c-border:    #E0DADA;

                                     /* Typography */
                                       --f-display:   'Playfair Display', Georgia, serif;
                                         --f-body:      'Inter', system-ui, sans-serif;
                                           --f-mono:      'Space Mono', monospace;

                                             /* Spacing */
                                               --s-xs:  0.5rem;
                                                 --s-sm:  1rem;
                                                   --s-md:  2rem;
                                                     --s-lg:  4rem;
                                                       --s-xl:  6rem;

                                                         /* Layout */
                                                           --max-w: 1200px;
                                                             --radius: 12px;
                                                               --radius-sm: 6px;

                                                                 /* Motion */
                                                                   --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
                                                                     --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);

                                                                       /* Font scale */
                                                                         --font-scale: 1;
                                                                         }

                                                                         /* ── 2. RESET ──────────────────────────────────────────── */
                                                                         *, *::before, *::after {
                                                                           box-sizing: border-box;
                                                                             margin: 0;
                                                                               padding: 0;
                                                                               }

                                                                               html {
                                                                                 scroll-behavior: smooth;
                                                                                   font-size: calc(16px * var(--font-scale));
                                                                                   }

                                                                                   body {
                                                                                     font-family: var(--f-body);
                                                                                       color: var(--c-ink);
                                                                                         background: var(--c-cream);
                                                                                           line-height: 1.7;
                                                                                             overflow-x: hidden;
                                                                                             }

                                                                                             img {
                                                                                               max-width: 100%;
                                                                                                 height: auto;
                                                                                                   display: block;
                                                                                                   }

                                                                                                   ul {
                                                                                                     list-style: none;
                                                                                                     }

                                                                                                     a {
                                                                                                       color: inherit;
                                                                                                         text-decoration: none;
                                                                                                         }

                                                                                                         button {
                                                                                                           font-family: var(--f-body);
                                                                                                             cursor: pointer;
                                                                                                               border: none;
                                                                                                                 background: none;
                                                                                                                 }

                                                                                                                 /* ── 3. HIGH CONTRAST MODE ─────────────────────────────── */
                                                                                                                 body.high-contrast {
                                                                                                                   --c-cream:    #000000;
                                                                                                                     --c-ink:      #FFFFFF;
                                                                                                                       --c-mid:      #CCCCCC;
                                                                                                                         --c-field:    #00FF00;
                                                                                                                           --c-straw:    #FFFF00;
                                                                                                                             --c-ocean:    #00CCFF;
                                                                                                                               --c-border:   #FFFFFF;
                                                                                                                                 --c-white:    #000000;
                                                                                                                                   background:   #000000;
                                                                                                                                   }

                                                                                                                                   body.high-contrast .site-header { background: #000; border-bottom: 2px solid #FFF; }
                                                                                                                                   body.high-contrast .btn-primary  { background: #FFFF00; color: #000; }
                                                                                                                                   body.high-contrast .btn-ghost    { border-color: #FFF; color: #FFF; }

                                                                                                                                   /* ── 4. ACCESSIBILITY BAR ──────────────────────────────── */
                                                                                                                                   .access-bar {
                                                                                                                                     position: fixed;
                                                                                                                                       top: 50%;
                                                                                                                                         right: -160px;
                                                                                                                                           transform: translateY(-50%);
                                                                                                                                             z-index: 1000;
                                                                                                                                               display: flex;
                                                                                                                                                 flex-direction: column;
                                                                                                                                                   gap: var(--s-xs);
                                                                                                                                                     align-items: flex-end;
                                                                                                                                                       transition: right 0.4s var(--ease-out);
                                                                                                                                                       }

                                                                                                                                                       .access-bar.open {
                                                                                                                                                         right: var(--s-sm);
                                                                                                                                                         }

                                                                                                                                                         .access-toggle {
                                                                                                                                                           background: var(--c-field);
                                                                                                                                                             color: var(--c-white);
                                                                                                                                                               width: 46px;
                                                                                                                                                                 height: 46px;
                                                                                                                                                                   border-radius: 50%;
                                                                                                                                                                     font-size: 1.2rem;
                                                                                                                                                                       display: flex;
                                                                                                                                                                         align-items: center;
                                                                                                                                                                           justify-content: center;
                                                                                                                                                                             box-shadow: 0 4px 20px rgba(0,0,0,0.3);
                                                                                                                                                                               position: absolute;
                                                                                                                                                                                 left: -56px;
                                                                                                                                                                                   top: 50%;
                                                                                                                                                                                     transform: translateY(-50%);
                                                                                                                                                                                       transition: background 0.2s;
                                                                                                                                                                                       }

                                                                                                                                                                                       .access-toggle:hover {
                                                                                                                                                                                         background: var(--c-soy);
                                                                                                                                                                                         }

                                                                                                                                                                                         .access-btn {
                                                                                                                                                                                           background: var(--c-white);
                                                                                                                                                                                             color: var(--c-ink);
                                                                                                                                                                                               border: 2px solid var(--c-border);
                                                                                                                                                                                                 border-radius: var(--radius-sm);
                                                                                                                                                                                                   padding: 0.4rem 0.8rem;
                                                                                                                                                                                                     font-weight: 600;
                                                                                                                                                                                                       font-size: 0.85rem;
                                                                                                                                                                                                         box-shadow: 0 2px 8px rgba(0,0,0,0.15);
                                                                                                                                                                                                           transition: background 0.2s, color 0.2s;
                                                                                                                                                                                                           }

                                                                                                                                                                                                           .access-btn:hover {
                                                                                                                                                                                                             background: var(--c-field);
                                                                                                                                                                                                               color: var(--c-white);
                                                                                                                                                                                                                 border-color: var(--c-field);
                                                                                                                                                                                                                 }

                                                                                                                                                                                                                 /* ── 5. HEADER & NAV ───────────────────────────────────── */
                                                                                                                                                                                                                 .site-header {
                                                                                                                                                                                                                   position: fixed;
                                                                                                                                                                                                                     top: 0;
                                                                                                                                                                                                                       left: 0;
                                                                                                                                                                                                                         right: 0;
                                                                                                                                                                                                                           z-index: 900;
                                                                                                                                                                                                                             background: rgba(250, 247, 242, 0.92);
                                                                                                                                                                                                                               backdrop-filter: blur(16px);
                                                                                                                                                                                                                                 -webkit-backdrop-filter: blur(16px);
                                                                                                                                                                                                                                   border-bottom: 1px solid transparent;
                                                                                                                                                                                                                                     transition: border-color 0.3s, box-shadow 0.3s;
                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                     .site-header.scrolled {
                                                                                                                                                                                                                                       border-color: var(--c-border);
                                                                                                                                                                                                                                         box-shadow: 0 2px 20px rgba(0,0,0,0.08);
                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                         .nav-inner {
                                                                                                                                                                                                                                           max-width: var(--max-w);
                                                                                                                                                                                                                                             margin: 0 auto;
                                                                                                                                                                                                                                               padding: 0 var(--s-md);
                                                                                                                                                                                                                                                 height: 68px;
                                                                                                                                                                                                                                                   display: flex;
                                                                                                                                                                                                                                                     align-items: center;
                                                                                                                                                                                                                                                       justify-content: space-between;
                                                                                                                                                                                                                                                         gap: var(--s-md);
                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                         .nav-logo {
                                                                                                                                                                                                                                                           display: flex;
                                                                                                                                                                                                                                                             align-items: center;
                                                                                                                                                                                                                                                               gap: 0.5rem;
                                                                                                                                                                                                                                                                 font-family: var(--f-display);
                                                                                                                                                                                                                                                                   font-size: 1.3rem;
                                                                                                                                                                                                                                                                     font-weight: 700;
                                                                                                                                                                                                                                                                       color: var(--c-soil);
                                                                                                                                                                                                                                                                         flex-shrink: 0;
                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                         .logo-icon { font-size: 1.5rem; }

                                                                                                                                                                                                                                                                         .logo-accent {
                                                                                                                                                                                                                                                                           color: var(--c-soy);
                                                                                                                                                                                                                                                                             margin: 0 0.1em;
                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                             .nav-menu {
                                                                                                                                                                                                                                                                               display: flex;
                                                                                                                                                                                                                                                                                 align-items: center;
                                                                                                                                                                                                                                                                                   gap: var(--s-xs);
                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                   .nav-menu a {
                                                                                                                                                                                                                                                                                     font-size: 0.88rem;
                                                                                                                                                                                                                                                                                       font-weight: 500;
                                                                                                                                                                                                                                                                                         color: var(--c-mid);
                                                                                                                                                                                                                                                                                           padding: 0.4rem 0.75rem;
                                                                                                                                                                                                                                                                                             border-radius: var(--radius-sm);
                                                                                                                                                                                                                                                                                               transition: color 0.2s, background 0.2s;
                                                                                                                                                                                                                                                                                               }

                                                                                                                                                                                                                                                                                               .nav-menu a:hover {
                                                                                                                                                                                                                                                                                                 color: var(--c-field);
                                                                                                                                                                                                                                                                                                   background: rgba(58, 90, 42, 0.08);
                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                   .nav-hamburger {
                                                                                                                                                                                                                                                                                                     display: none;
                                                                                                                                                                                                                                                                                                       flex-direction: column;
                                                                                                                                                                                                                                                                                                         gap: 5px;
                                                                                                                                                                                                                                                                                                           width: 36px;
                                                                                                                                                                                                                                                                                                             padding: 4px;
                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                             .nav-hamburger span {
                                                                                                                                                                                                                                                                                                               display: block;
                                                                                                                                                                                                                                                                                                                 height: 2px;
                                                                                                                                                                                                                                                                                                                   background: var(--c-ink);
                                                                                                                                                                                                                                                                                                                     border-radius: 2px;
                                                                                                                                                                                                                                                                                                                       transition: transform 0.3s, opacity 0.3s;
                                                                                                                                                                                                                                                                                                                       }

                                                                                                                                                                                                                                                                                                                       .nav-hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
                                                                                                                                                                                                                                                                                                                       .nav-hamburger.active span:nth-child(2) { opacity: 0; }
                                                                                                                                                                                                                                                                                                                       .nav-hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

                                                                                                                                                                                                                                                                                                                       /* ── 6. BUTTONS ────────────────────────────────────────── */
                                                                                                                                                                                                                                                                                                                       .btn-primary {
                                                                                                                                                                                                                                                                                                                         display: inline-flex;
                                                                                                                                                                                                                                                                                                                           align-items: center;
                                                                                                                                                                                                                                                                                                                             gap: 0.5rem;
                                                                                                                                                                                                                                                                                                                               background: var(--c-field);
                                                                                                                                                                                                                                                                                                                                 color: var(--c-white);
                                                                                                                                                                                                                                                                                                                                   padding: 0.85rem 1.8rem;
                                                                                                                                                                                                                                                                                                                                     border-radius: 100px;
                                                                                                                                                                                                                                                                                                                                       font-weight: 600;
                                                                                                                                                                                                                                                                                                                                         font-size: 0.95rem;
                                                                                                                                                                                                                                                                                                                                           transition: background 0.25s, transform 0.25s var(--ease-spring), box-shadow 0.25s;
                                                                                                                                                                                                                                                                                                                                             border: 2px solid transparent;
                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                             .btn-primary:hover {
                                                                                                                                                                                                                                                                                                                                               background: var(--c-soy);
                                                                                                                                                                                                                                                                                                                                                 transform: translateY(-2px);
                                                                                                                                                                                                                                                                                                                                                   box-shadow: 0 8px 24px rgba(58,90,42,0.3);
                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                   .btn-primary:active {
                                                                                                                                                                                                                                                                                                                                                     transform: translateY(0);
                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                     .btn-ghost {
                                                                                                                                                                                                                                                                                                                                                       display: inline-flex;
                                                                                                                                                                                                                                                                                                                                                         align-items: center;
                                                                                                                                                                                                                                                                                                                                                           gap: 0.5rem;
                                                                                                                                                                                                                                                                                                                                                             background: transparent;
                                                                                                                                                                                                                                                                                                                                                               color: var(--c-white);
                                                                                                                                                                                                                                                                                                                                                                 padding: 0.85rem 1.8rem;
                                                                                                                                                                                                                                                                                                                                                                   border-radius: 100px;
                                                                                                                                                                                                                                                                                                                                                                     font-weight: 600;
                                                                                                                                                                                                                                                                                                                                                                       font-size: 0.95rem;
                                                                                                                                                                                                                                                                                                                                                                         border: 2px solid rgba(255,255,255,0.6);
                                                                                                                                                                                                                                                                                                                                                                           transition: background 0.25s, border-color 0.25s, transform 0.25s var(--ease-spring);
                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                           .btn-ghost:hover {
                                                                                                                                                                                                                                                                                                                                                                             background: rgba(255,255,255,0.15);
                                                                                                                                                                                                                                                                                                                                                                               border-color: var(--c-white);
                                                                                                                                                                                                                                                                                                                                                                                 transform: translateY(-2px);
                                                                                                                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                                                                                                                 /* ── 7. SECTION HELPERS ────────────────────────────────── */
                                                                                                                                                                                                                                                                                                                                                                                 .section {
                                                                                                                                                                                                                                                                                                                                                                                   padding: var(--s-xl) 0;
                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                   .container {
                                                                                                                                                                                                                                                                                                                                                                                     max-width: var(--max-w);
                                                                                                                                                                                                                                                                                                                                                                                       margin: 0 auto;
                                                                                                                                                                                                                                                                                                                                                                                         padding: 0 var(--s-md);
                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                         .section-label {
                                                                                                                                                                                                                                                                                                                                                                                           font-family: var(--f-mono);
                                                                                                                                                                                                                                                                                                                                                                                             font-size: 0.78rem;
                                                                                                                                                                                                                                                                                                                                                                                               letter-spacing: 0.18em;
                                                                                                                                                                                                                                                                                                                                                                                                 text-transform: uppercase;
                                                                                                                                                                                                                                                                                                                                                                                                   color: var(--c-soy);
                                                                                                                                                                                                                                                                                                                                                                                                     margin-bottom: var(--s-sm);
                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                     .section-label.light {
                                                                                                                                                                                                                                                                                                                                                                                                       color: rgba(123,175,63,0.85);
                                                                                                                                                                                                                                                                                                                                                                                                       }

                                                                                                                                                                                                                                                                                                                                                                                                       .section-title {
                                                                                                                                                                                                                                                                                                                                                                                                         font-family: var(--f-display);
                                                                                                                                                                                                                                                                                                                                                                                                           font-size: clamp(2rem, 4vw, 3.2rem);
                                                                                                                                                                                                                                                                                                                                                                                                             font-weight: 900;
                                                                                                                                                                                                                                                                                                                                                                                                               color: var(--c-soil);
                                                                                                                                                                                                                                                                                                                                                                                                                 line-height: 1.15;
                                                                                                                                                                                                                                                                                                                                                                                                                   margin-bottom: var(--s-sm);
                                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                                                   .section-title.light {
                                                                                                                                                                                                                                                                                                                                                                                                                     color: var(--c-white);
                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                     .section-desc {
                                                                                                                                                                                                                                                                                                                                                                                                                       font-size: 1.1rem;
                                                                                                                                                                                                                                                                                                                                                                                                                         color: var(--c-mid);
                                                                                                                                                                                                                                                                                                                                                                                                                           max-width: 640px;
                                                                                                                                                                                                                                                                                                                                                                                                                             margin-bottom: var(--s-lg);
                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                             .section-desc.light {
                                                                                                                                                                                                                                                                                                                                                                                                                               color: rgba(255,255,255,0.75);
                                                                                                                                                                                                                                                                                                                                                                                                                               }

                                                                                                                                                                                                                                                                                                                                                                                                                               /* ── 8. REVEAL ANIMATION ───────────────────────────────── */
                                                                                                                                                                                                                                                                                                                                                                                                                               .reveal {
                                                                                                                                                                                                                                                                                                                                                                                                                                 opacity: 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                   transform: translateY(28px);
                                                                                                                                                                                                                                                                                                                                                                                                                                     transition: opacity 0.7s var(--ease-out), transform 0.7s var(--ease-out);
                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                     .reveal.visible {
                                                                                                                                                                                                                                                                                                                                                                                                                                       opacity: 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                         transform: translateY(0);
                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                         @media (prefers-reduced-motion: reduce) {
                                                                                                                                                                                                                                                                                                                                                                                                                                           .reveal {
                                                                                                                                                                                                                                                                                                                                                                                                                                               opacity: 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                   transform: none;
                                                                                                                                                                                                                                                                                                                                                                                                                                                       transition: none;
                                                                                                                                                                                                                                                                                                                                                                                                                                                         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                         /* ── 9. HERO ───────────────────────────────────────────── */
                                                                                                                                                                                                                                                                                                                                                                                                                                                         .hero {
                                                                                                                                                                                                                                                                                                                                                                                                                                                           position: relative;
                                                                                                                                                                                                                                                                                                                                                                                                                                                             min-height: 100vh;
                                                                                                                                                                                                                                                                                                                                                                                                                                                               display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                 flex-direction: column;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                   justify-content: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                     overflow: hidden;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                       background: linear-gradient(135deg, var(--c-soil) 0%, #1A3A14 50%, var(--c-ocean) 100%);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                       .hero-bg-overlay {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                         position: absolute;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                           inset: 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                             background:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 radial-gradient(ellipse 80% 60% at 20% 80%, rgba(123,175,63,0.12) 0%, transparent 60%),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     radial-gradient(ellipse 60% 80% at 80% 20%, rgba(27,79,114,0.2) 0%, transparent 60%);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       pointer-events: none;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       .hero-canvas {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         position: absolute;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           inset: 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             width: 100%;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               height: 100%;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 opacity: 0.35;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 .hero-content {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   position: relative;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     z-index: 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       max-width: var(--max-w);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         margin: 0 auto;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           padding: calc(68px + var(--s-xl)) var(--s-md) var(--s-lg);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               flex-direction: column;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 align-items: flex-start;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   gap: var(--s-sm);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   .hero-eyebrow {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     font-family: var(--f-mono);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       font-size: 0.82rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         letter-spacing: 0.16em;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           text-transform: uppercase;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             color: var(--c-straw);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               transition-delay: 0.1s;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               .hero-title {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 font-family: var(--f-display);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   font-size: clamp(3rem, 7vw, 6.5rem);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     font-weight: 900;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       color: var(--c-white);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         line-height: 0.95;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           transition-delay: 0.2s;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           .hero-accent {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             color: var(--c-straw);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               display: block;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               .hero-sub {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 max-width: 560px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   font-size: 1.1rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     color: rgba(255,255,255,0.8);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       line-height: 1.65;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         transition-delay: 0.3s;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         .hero-cta {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             gap: var(--s-sm);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               flex-wrap: wrap;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 transition-delay: 0.4s;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   padding-top: 0.5rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   .hero-scroll-hint {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     position: absolute;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       bottom: var(--s-md);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         left: 50%;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           transform: translateX(-50%);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               flex-direction: column;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 align-items: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   gap: 0.5rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     color: rgba(255,255,255,0.5);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       font-size: 0.75rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         letter-spacing: 0.1em;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           text-transform: uppercase;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             z-index: 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             .scroll-arrow {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               width: 20px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 height: 20px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   border-right: 2px solid rgba(255,255,255,0.4);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     border-bottom: 2px solid rgba(255,255,255,0.4);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       transform: rotate(45deg);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         animation: scrollBounce 1.5s ease-in-out infinite;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         @keyframes scrollBounce {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           0%, 100% { transform: rotate(45deg) translateY(0); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             50%       { transform: rotate(45deg) translateY(6px); }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             /* Hero stats bar */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             .hero-stats {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               position: relative;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 z-index: 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   background: rgba(255,255,255,0.06);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     backdrop-filter: blur(10px);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       -webkit-backdrop-filter: blur(10px);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         border-top: 1px solid rgba(255,255,255,0.1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           display: grid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             grid-template-columns: 1fr 1px 1fr 1px 1fr;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               max-width: 100%;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 margin-top: auto;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 .stat-item {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   padding: var(--s-md) var(--s-lg);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       flex-direction: column;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         align-items: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           text-align: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             gap: 0.25rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               transition-delay: 0.5s;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               .stat-num {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 font-family: var(--f-display);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   font-size: clamp(2rem, 4vw, 3.5rem);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     font-weight: 900;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       color: var(--c-straw);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         line-height: 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         .stat-unit {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           font-family: var(--f-mono);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             font-size: 0.85rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               color: var(--c-straw);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 opacity: 0.7;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   align-self: flex-end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     margin-bottom: 0.25rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       margin-left: 2px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       .stat-label {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         font-size: 0.8rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           color: rgba(255,255,255,0.6);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             max-width: 200px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               line-height: 1.4;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               .stat-divider {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 background: rgba(255,255,255,0.12);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   width: 1px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   /* ── 10. SOBRE ─────────────────────────────────────────── */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   .sobre {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     background: var(--c-cream);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     .sobre-grid {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       display: grid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         grid-template-columns: 1fr 1fr;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           gap: var(--s-lg);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             align-items: start;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             .sobre-text p {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               color: var(--c-mid);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 margin-bottom: var(--s-sm);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   font-size: 1.05rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   .sobre-text strong {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     color: var(--c-field);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     .sobre-cards {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       display: grid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         grid-template-columns: 1fr 1fr;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           gap: var(--s-sm);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           .mini-card {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             background: var(--c-white);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               border: 1px solid var(--c-border);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 border-radius: var(--radius);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   padding: var(--s-md) var(--s-sm);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       flex-direction: column;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         gap: 0.4rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           transition: transform 0.3s var(--ease-spring), box-shadow 0.3s;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           .mini-card:hover {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             transform: translateY(-4px);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               box-shadow: 0 8px 24px rgba(0,0,0,0.1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               .mini-icon {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 font-size: 1.8rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 .mini-card strong {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   font-size: 1rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     color: var(--c-soil);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     .mini-card span {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       font-size: 0.85rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         color: var(--c-mid);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         /* ── 11. JORNADA / TIMELINE ────────────────────────────── */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         .jornada {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           background: linear-gradient(180deg, var(--c-cream) 0%, #EDF4E8 100%);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           .timeline {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             position: relative;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 flex-direction: column;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   gap: var(--s-lg);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   .timeline::before {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     content: '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       position: absolute;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         left: 50%;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           top: 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             bottom: 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               width: 2px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 background: linear-gradient(180deg, var(--c-soy) 0%, var(--c-ocean) 100%);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   transform: translateX(-50%);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   .timeline-item {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     display: grid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       grid-template-columns: 1fr auto 1fr;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         gap: var(--s-md);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           align-items: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             position: relative;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             .timeline-item:nth-child(even) .timeline-body {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               grid-column: 3;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 grid-row: 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 .timeline-item:nth-child(odd) .timeline-body {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   grid-column: 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   .timeline-marker {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     grid-column: 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       width: 56px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         height: 56px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           border-radius: 50%;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             background: var(--c-field);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               color: var(--c-white);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 font-family: var(--f-mono);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   font-weight: 700;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     font-size: 0.9rem;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       display: flex;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         align-items: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           justify-content: center;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             z-index: 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               box-shadow: 0 0 0 6px var(--c-cream), 0 0 0 8px var(--c-soy);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 flex-shrink: 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 .timeline-body {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   background: var(--c-white);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     border-radius: var(--radius);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       border: 1px solid var(--c-border);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         overflow: hidden;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           box-shadow: 0 4px 16px rgba(0,0,0,0.06);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             transition: box-shadow 0.3s, transform 0.3s var(--ease-spring);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             .timeline-body:hover {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               box-shadow: 0 12px 32px rgba(0,0,0,0.12);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 transform: translateY(-4px);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 .timeline-img {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   height: 200px;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     overflow: hidden;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       background: #E8EDE5;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       .timeline-img img {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         width: 100%;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           height: 100%;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             object-fit: cover;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               transition: transform 0.5s var(--ease-out);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               .timeline-body:hover .timeline-img img {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 transform: scale(1.04);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }

